var SelectedDrawable=0;
tinymce.PluginManager.add('ifbq_drawables', function(editor, url) {
	
	CurrVarName = (CurrVarName) ?CurrVarName :'' ;
	editor.ui.registry.addButton('drawables', {
		text: 'Zeichnen',
		icon: 'table',
		image: tinymce.baseURL + '/plugins/ifbq_drawables/drawicon.png',
		id: 'drawable_antwortElement',
		class: 'drawables',
		tooltip:'Antwortelement',
		stateSelector:"img .drawables",
		onAction: ShowDrawWindow
	});
});
